
INSERT INTO public.contract_models (
  company_id,
  nome_modelo,
  tipo_evento,
  conteudo_template,
  is_active,
  versao,
  descricao
) VALUES (
  'eb1776f0-142e-41db-9134-7d352d02c5bd',
  'Contrato Festa',
  'Festa Infantil',
  E'![Logo]({{logo_url}})\n\n# CONTRATO DE FESTA ESPAÇO AVENTURA KIDS\n\n# Contrato de Prestação de Serviço de Buffet Infantil\n\n# CONTRATADO:\n\nEspaço Aventura Kids, pessoa jurídica de direito privado, inscrita no CNPJ nº 55.369.377/0001-04, com sede na Rua Canadá, nº 51, Bairro Jardim Novo Mundo, Município de São Gotardo/MG, neste ato representada por sua proprietária Sra. Fernanda Garcia de Oliveira, doravante denominado CONTRATADO.\n\n# CONTRATANTE:\n\nNome: {{nome_completo}}\n\nCPF: {{cpf}}\n\nRG: {{rg}}\n\nData de nascimento: {{data_nascimento}}\n\nEndereço: {{endereco}}, {{numero}}\n\nBairro: {{bairro}} – CEP: {{cep}}\n\nCidade: {{cidade}}/{{estado}}\n\nE-mail: {{email}}\n\n# DADOS DO EVENTO:\n\nAniversariante: {{nome_aniversariante}}\n\nIdade: {{idade_aniversariante}}\n\nData do evento: {{data_evento}}\n\nHorário: {{horario}} às {{horario_fim}}\n\nPacote: {{pacote}}\n\nQuantidade: {{quantidade_pessoas}} pessoas\n\n# Cláusula 1ª)\n\nO presente contrato tem por objeto a prestação de serviços de buffet infantil, bem como a cessão do espaço para realização do evento descrito acima.\n\nO CONTRATADO se compromete a fornecer toda a estrutura, equipe e materiais necessários para execução do evento, conforme o pacote contratado.\n\n# Cláusula 2ª.) VALORES E PAGAMENTO\n\nVALOR TOTAL: O valor total pelos serviços e cessão de espaço é de {{valor_total}} ({{valor_total_extenso}}).\n\n# FORMA DE PAGAMENTO:\n\nO pagamento será realizado da seguinte forma:\n\n**Sinal:** {{valor_sinal}}, com vencimento em {{data_entrada}}.\n\n**Saldo:** {{valor_restante}}, com vencimento em {{data_saldo}}.\n\n# OPCIONAIS:\n\n{{opcionais}}\n\n# Cláusula 3ª\n\nO serviço do buffet terá início a partir do horário combinado, conforme estabelecido no presente contrato, e terá duração de {{duracao_festa}}, com direito a 15 (quinze) minutos de tolerância, que poderá ser computado ao final do evento.\n\n# Cláusula 4ª\n\nCaso o(a) CONTRATANTE exceda o limite de tolerância de 15 (quinze) minutos, será cobrado o valor de R$ 300,00 (trezentos reais) por cada período adicional de 30 (trinta) minutos, ou fração, a título de hora excedente.\n\nA permanência no local após o horário contratado caracteriza a aceitação automática da cobrança. O valor deverá ser quitado imediatamente ao término do evento.\n\n# Cláusula 5ª\n\nO salão será disponibilizado à(o) CONTRATANTE, 15 (quinze) minutos antes do horário estabelecido para o início do evento, sendo certo que os serviços somente serão iniciados na hora prevista para o início do evento.\n\n# Cláusula 6ª\n\nO número de convidados do(a) CONTRATANTE é de {{quantidade_pessoas}} pessoas. Fica pactuado entre as partes contratantes que, na hipótese de não comparecimento de todas as pessoas previstas neste contrato, não haverá restituição proporcional dos valores pagos. Se estendendo também a regra para possíveis convidados adicionais contratados.\n\n# Cláusula 7ª\n\nO não comparecimento do número previsto de convidados não implicará na redução do preço total do evento contratado.\n\n# Cláusula 8ª\n\nCrianças com até 4 anos serão consideradas como cortesia do ESPAÇO AVENTURA KIDS, não sendo computadas para efeito de cobrança.\n\nParágrafo único. As crianças que permanecerem nas dependências do evento sem o acompanhamento de seus pais, responsáveis legais ou adulto indicado pela CONTRATANTE estarão sob inteira e exclusiva responsabilidade da CONTRATANTE, ficando o CONTRATADO isento de responsabilidade por acidentes, quedas, mau uso dos brinquedos ou quaisquer ocorrências envolvendo tais menores, ressalvadas as hipóteses de culpa comprovada do CONTRATADO.\n\n# Cláusula 9ª\n\nO controle de convidados será feito em lista nominal. É obrigação do(a) CONTRATANTE ou de pessoa por Ele(a) designada, acompanhar o seu preenchimento, sendo-lhe assegurado o direito de contestar durante a realização do evento. Não sendo aceito, averiguação, reclamação e/ou devolução de valores após o evento.\n\n# Cláusula 10ª\n\nSe o(a) CONTRATANTE desejar alterar a data da realização do evento, deverá comunicar previamente o ESPAÇO AVENTURA KIDS.\n\nO CONTRATADO procederá com a alteração, desde que haja disponibilidade na agenda de eventos do buffet dentro do ano contratado. Caso o(a) CONTRATANTE deseje a alteração para o ano seguinte, deverá arcar com as custas referentes ao reequilíbrio de custos decorrentes da mudança.\n\nA transferência do evento será possível desde que não haja reserva para o dia e horário desejados.\n\nSe a transferência for solicitada com menos de 60 (sessenta) dias, incidirá uma taxa de 20% (vinte por cento) sobre o valor total do contrato.\n\nPara alteração de data solicitada com menos de 48 (quarenta e oito) horas antes do evento, incidirá multa de 50% (cinquenta por cento) sobre o valor contratado, a título de indenização por perdas e danos.\n\nEm caso de doença, falecimento ou algum acidente envolvendo, exclusivamente, o aniversariante, pai, mãe ou irmãos do aniversariante, será necessária a apresentação de documento médico que comprove a doença e a impossibilidade da realização do evento.\n\n# Cláusula 11ª\n\nA falta de pagamento nos prazos estipulados sujeita o CONTRATANTE ao pagamento de juros legais e atualização monetária com base na variação do IGPM/GV, a partir da data de vencimento, além de despesas bancárias, sem prejuízo da rescisão do contrato que poderá ser exigida pelo CONTRATADO.\n\n# Cláusula 12ª\n\nEm caso de inadimplência, fica autorizado a inclusão do nome do(a) CONTRATANTE junto aos órgãos de proteção ao crédito, permanecendo as negativações até a quitação do débito.\n\n# Cláusula 13ª\n\nNo caso de atraso no pagamento da(s) parcela(s), arcará o(a) CONTRATANTE com multa de 10% (dez por cento), além de juros de mora de 1% ao mês e correção monetária pela variação do IGP-M da Fundação Getúlio Vargas.\n\n# Cláusula 14ª\n\nO não pagamento, total ou parcial de quaisquer das parcelas, será interpretado como desistência do evento, acarretando o seu imediato cancelamento, independente de qualquer aviso ou notificação.\n\n# Cláusula 15ª\n\nO(a) CONTRATANTE poderá aumentar o número de convidados, devendo para tanto comunicar o ESPAÇO AVENTURA KIDS em até no máximo 10 (DEZ) dias que antecedem o evento, sob pena dos serviços atenderem apenas a demanda contratada.\n\n# Cláusula 16ª\n\nCaso o número de convidados ultrapasse o número já contratado, o valor adicional por convidado será: {{valor_convidado_adicional}} por convidados adicionais.\n\n# Cláusula 17ª\n\nO valor correspondente aos "convidados adicionais", deverá ser pago à vista e ao final do evento, sob pena de sofrer acréscimo de 10% (dez por cento).\n\n# Cláusula 18ª\n\nObriga-se o ESPAÇO AVENTURA KIDS a reservar o seu espaço e garantir a qualidade de seus serviços, desde que o número total de convidados presentes não exceda a 10% (dez por cento) do número previamente contratado, sem prejuízo da cobrança do valor previsto para "convidado adicional", nos termos deste contrato.\n\n# Cláusula 19ª\n\nNão está incluída em nenhum dos nossos pacotes bebida alcoólica. A disponibilização de bebidas alcoólicas no evento não está inclusa nos pacotes contratados, sendo de inteira responsabilidade do(a) CONTRATANTE o fornecimento, aquisição, controle e distribuição das referidas bebidas.\n\nCaso o(a) CONTRATANTE opte por servir bebidas alcoólicas, será obrigatória a contratação de garçom adicional, no valor de R$ 180,00 (cento e oitenta reais), a ser pago antecipadamente, juntamente com os demais valores do contrato.\n\nCaso o(a) CONTRATANTE opte pela disponibilização de chopp no evento, deverá comunicar previamente o CONTRATADO, com antecedência mínima de 02 (dois) dias, para análise de viabilidade e organização do espaço.\n\nO fornecimento, instalação, equipamentos, operação, barris, cilindros, chopeiras e quaisquer itens necessários para o serviço de chopp serão de inteira responsabilidade do(a) CONTRATANTE ou de terceiros por ele(a) contratados.\n\nFica vedada a instalação de equipamentos sem prévia autorização do CONTRATADO.\n\nParágrafo único: A responsabilidade pelo consumo de bebidas alcoólicas, inclusive chopp, pelos convidados é exclusiva do(a) CONTRATANTE, ficando o CONTRATADO isento de quaisquer responsabilidades decorrentes do uso indevido, excessivo ou inadequado, incluindo, mas não se limitando a, acidentes, danos, comportamentos inadequados ou quaisquer ocorrências relacionadas ao consumo de álcool.\n\n# Cláusula 20ª.) CANCELAMENTO PELA CONTRATANTE:\n\nSe o cancelamento ocorrer com mais de 60 (sessenta) dias de antecedência da data do evento, a AVENTURA KIDS devolverá 50% do valor do sinal pago.\n\nSe o cancelamento ocorrer entre 30 (trinta) e 60 (sessenta) dias de antecedência, o valor do sinal será retido integralmente pela AVENTURA KIDS para cobrir custos administrativos e perda de oportunidade.\n\nSe o cancelamento ocorrer com menos de 30 (trinta) dias de antecedência, além da retenção do sinal, a CONTRATANTE deverá pagar uma multa de 30% sobre o valor total do contrato, caso o saldo já tenha sido pago. Se o saldo não tiver sido pago, o sinal será retido e a multa será cobrada sobre o valor restante.\n\n# Cláusula 21ª.) REMARCAÇÃO:\n\nA remarcação do evento poderá ser solicitada pela CONTRATANTE com no mínimo 60 (sessenta) dias de antecedência, sujeita à disponibilidade de data da AVENTURA KIDS e ao pagamento de uma taxa administrativa de 10% sobre o valor total do contrato. Remarcações com menos de 60 (sessenta) dias de antecedência serão tratadas como cancelamento.\n\n# Cláusula 22ª.)\n\nO ESPAÇO AVENTURA KIDS não será responsabilizado por problemas advindos de falhas dos serviços públicos, tais como suspensão de energia elétrica, água, etc. Se por motivo de caso fortuito ou de força maior não for possível realizar o evento, as partes em comum acordo definirão nova data, observando-se a disponibilidade da agenda do ESPAÇO AVENTURA KIDS. Caso o(a) CONTRATANTE desista do evento não haverá restituição dos valores pagos.\n\n# Cláusula 23ª.)\n\nO(a) CONTRATANTE será integralmente responsável por quaisquer danos causados ao espaço, seus equipamentos, mobiliários, utensílios e demais bens do ESPAÇO AVENTURA KIDS, inclusive aqueles provocados por seus convidados, menores sob sua responsabilidade ou terceiros por ele contratados.\n\nParágrafo primeiro: Consideram-se danos, entre outros, aqueles causados ao piso, paredes, brinquedos, equipamentos, mesas, cadeiras, utensílios (copos, pratos, talheres), toalhas e quaisquer itens pertencentes ao estabelecimento.\n\nParágrafo segundo: Os prejuízos deverão ser indenizados pelo(a) CONTRATANTE com base no valor de mercado do bem danificado ou no custo de reparo, conforme avaliação do CONTRATADO.\n\nParágrafo terceiro: O pagamento referente aos danos apurados deverá ser realizado imediatamente ao final do evento, à vista, como condição para encerramento da prestação de serviços.\n\n# Cláusula 24ª.)\n\nCaso haja acidente de qualquer natureza durante o evento sem a ocorrência de culpa ou dolo do ESPAÇO AVENTURA KIDS, este não terá nenhuma responsabilidade, podendo, se entender necessário prestar a assistência cabível.\n\n# Cláusula 25ª.)\n\nAo assinar este contrato, o CONTRATANTE está de acordo com o Uso de Imagem, pois o salão publica nas redes sociais, um vídeo com fotos do Evento realizado. Caso o CONTRATANTE não queira esta exposição, é necessário informar o CONTRATADO no ato do fechamento do contrato.\n\n# Cláusula 26ª.)\n\nO ESPAÇO AVENTURA KIDS não se responsabiliza por objetos esquecidos ou perdidos durante ou após a realização do evento.\n\n# Cláusula 27ª.)\n\nO ESPAÇO AVENTURA KIDS realiza periodicamente a manutenção preventiva dos brinquedos elétricos ou eletrônicos, porém, não será responsabilizado por brinquedos ou aparelhos que tenham quebrado de um evento para outro, sem tempo hábil para manutenção, nestes casos, O ESPAÇO AVENTURA KIDS se reserva o direito do não funcionamento de até 10% dos equipamentos eletrônicos oferecidos na locação do salão.\n\n# Cláusula 28ª.) Uso de Imagem e Dados Pessoais\n\n§1º O(a) CONTRATANTE autoriza o CONTRATADO a utilizar imagens (fotos e vídeos) do evento, que possam conter sua imagem, do aniversariante e dos convidados, para fins de divulgação e promoção dos serviços do ESPAÇO AVENTURA KIDS, em mídias sociais, website e materiais publicitários.\n\n§2º Caso o(a) CONTRATANTE não autorize o uso de imagem, deverá manifestar sua negativa por escrito no ato da assinatura do contrato ou com antecedência mínima de 7 (sete) dias da data do evento.\n\n§3º As partes declaram estar cientes e concordam que os dados pessoais coletados em razão deste contrato serão tratados em conformidade com a Lei nº 13.709/2018 (Lei Geral de Proteção de Dados – LGPD), sendo utilizados exclusivamente para a execução deste contrato, comunicação entre as partes e cumprimento de obrigações legais.\n\n§4º O CONTRATADO compromete-se a adotar medidas de segurança adequadas para proteção dos dados pessoais, garantindo sua confidencialidade e não os compartilhando com terceiros, salvo quando necessário para a execução do contrato ou por obrigação legal.\n\n# Cláusula 29ª.)\n\nO CONTRATADO poderá indicar ou autorizar a contratação de serviços de profissionais terceirizados, tais como fotógrafos, filmagem, recreação, shows, decoração, entre outros, os quais deverão ser contratados diretamente pelo(a) CONTRATANTE, não gerando ao CONTRATADO qualquer responsabilidade por tais serviços ou por eventuais danos deles decorrentes.\n\n§1º A contratação de profissionais terceirizados é de responsabilidade exclusiva do(a) CONTRATANTE.\n\n§2º Para acesso às dependências do evento, será cobrada taxa de R$ 50,00 (cinquenta reais) por profissional terceirizado, considerando a utilização da estrutura do espaço, bem como eventual consumo de alimentos, bebidas e demais serviços oferecidos pelo CONTRATADO, devendo o pagamento ser realizado previamente à data do evento.\n\n§3º O(a) CONTRATANTE obriga-se a informar previamente ao CONTRATADO a quantidade e, se solicitado, a identificação dos profissionais terceirizados que participarão do evento, com antecedência mínima de 5 (cinco) dias, para fins de controle, organização e liberação de acesso.\n\n§4º O acesso de profissionais terceirizados somente será permitido mediante prévia autorização do CONTRATADO e quitação da respectiva taxa.\n\n§5º O descumprimento do disposto nesta cláusula poderá acarretar a restrição de entrada dos profissionais não informados previamente, sem qualquer responsabilidade ao CONTRATADO.\n\n§6º Ainda que não haja consumo de alimentos ou bebidas, a taxa será devida em razão da utilização da estrutura e permanência no local.\n\n# Cláusula 30ª.)\n\nPor haver preparo e manutenção de alimentos, é proibida a entrada e permanência de animais em nosso Buffet.\n\n# Cláusula 31ª.)\n\nAs partes contratantes elegem o foro da cidade de São Gotardo, Estado de Minas Gerais, para dirimir quaisquer controvérsias oriundas deste contrato, renunciando a qualquer outro, por mais privilegiado que seja.\n\nSão Gotardo, {{data_contrato}}\n\n____________________________________\n\nCONTRATANTE\n\n{{nome_completo}}\n\nCPF {{cpf}}\n\n___________________________________\n\nCONTRATADO\n\nESPAÇO AVENTURA KIDS',
  true,
  1,
  'Contrato padrão para festas infantis do Espaço Aventura Kids com 31 cláusulas, incluindo LGPD e uso de imagem.'
);
